import sys
sys.path.insert(0,'/workspace/submission')
from crosscheck.common_utils import Topology, band_of_values, select_band
from crosscheck.dtp import compute_predictions
spec = {"nodes": [{"id": 0, "name": "A", "external_capacity": 10},
                  {"id": 1, "name": "B", "external_capacity": 10}],
        "links": [{"source": 0, "target": 1, "capacity": 10}],
        "external_nodes": ["A", "B"]}
t = Topology(spec)
counters = {"low_A_egress_to_B":4,"low_B_ingress_from_A":4,"low_A_origination":4,"low_B_termination":4}
demands = {(0,1):4}
routes = {(0,1):[((0,1),1000)], (1,0):[((1,0),1000)]}
class S: trials=1; epsilon=0; seed=3
pred, routed = compute_predictions(t, demands, routes)
print('pred', pred, routed)
trials=1; epsilon=0; seed=3
pools={}; ends={}
for f in t.flows:
    e=[]
    k=t.src_key.get(f)
    if k and counters.get(k) is not None: e.append(counters[k])
    k=t.dst_key.get(f)
    if k and counters.get(k) is not None: e.append(counters[k])
    if routed:
        v=pred[f]; c=t.flow_cap[f]
        e.append(min(v,c))
    pools[f]=e
    a,b=f; en=[]
    if a>=0: en.append((a,True))
    if b>=0: en.append((b,False))
    ends[f]=en
    print('pool',f,e,'ends',en)
from crosscheck.common_utils import scenario_weight
samples={}
for f in t.flows:
    p=pools[f]; L=len(p)
    for (r,out) in ends[f]:
        vals=[p[scenario_weight(seed,r,tt,f[0],f[1])%L] if L else 0 for tt in range(trials)]
        samples[(f,r)]=vals
inc={r:[0]*trials for r in t.node_ids}; out_={r:[0]*trials for r in t.node_ids}
for f in t.flows:
    for (r,out) in ends[f]:
        bkt = out_[r] if out else inc[r]
        for tt in range(trials): bkt[tt]+=samples[(f,r)][tt]
print('inc',inc,'out',out_)
def evidence(f):
    ent=[(v,trials) for v in pools[f]]
    cap=t.flow_cap[f]
    for (r,out) in ends[f]:
        vs=samples[(f,r)]; i=inc[r]; o=out_[r]
        if out: rem=[v+ii-oo for v,ii,oo in zip(vs,i,o)]
        else: rem=[v+oo-ii for v,ii,oo in zip(vs,i,o)]
        print('  router',r,'out' if out else 'in','rem',rem)
        rep,mass=band_of_values(rem,epsilon)
        print('  -> rep',rep,'mass',mass)
        ent.append((rep,mass))
    print('  entries',ent)
    return select_band(ent,epsilon)
for f in t.flows:
    print(f, evidence(f))
